<?php
namespace App\Http\Controllers;
use App\Actions\Procurement\{ConfirmGoodsReceiptAction,ConfirmPurchaseReturnAction,CreatePurchaseOrderAction,RecordSupplierPaymentAction};
use App\Models\{GoodsReceipt,PurchaseOrder,PurchaseReturn,Supplier,SupplierInvoice};
use App\Services\CodeGeneratorService;
use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule;
class ProcurementController extends Controller {
 public function suppliers(Request $r){return response()->json(Supplier::query()->with('contacts')->when($r->search,fn($q,$s)=>$q->where('name','like',"%$s%"))->paginate(15));}
 public function storeSupplier(Request $r):RedirectResponse{$data=$r->validate(['name'=>'required|string|max:255','code'=>'required|string|max:255|unique:suppliers,code','phone'=>'nullable|string','email'=>'nullable|email','address'=>'nullable|string','tax_number'=>'nullable|string|unique:suppliers,tax_number','notes'=>'nullable|string','status'=>['nullable',Rule::in(['active','inactive'])]]);$supplier=Supplier::create($data+['status'=>$data['status']??'active']);return back()->with('success',"Supplier {$supplier->name} created.");}
 public function storePurchaseOrder(Request $r,CreatePurchaseOrderAction $a):RedirectResponse{$d=$r->validate(['supplier_id'=>'required|exists:suppliers,id','order_date'=>'required|date','expected_delivery_date'=>'nullable|date','notes'=>'nullable|string','discount'=>'nullable|numeric|min:0','tax'=>'nullable|numeric|min:0','items'=>'required|array|min:1','items.*.product_variant_id'=>'required|exists:product_variants,id','items.*.quantity'=>'required|integer|min:1','items.*.unit_price'=>'required|numeric|min:0','items.*.discount'=>'nullable|numeric|min:0','items.*.tax'=>'nullable|numeric|min:0']);$d['discount']=$d['discount']??0;$d['tax']=$d['tax']??0;foreach($d['items'] as &$i){$i['discount']=$i['discount']??0;$i['tax']=$i['tax']??0;}return redirect()->route('purchase-orders.show',$a->handle($d))->with('success','Purchase order created.');}
 public function showPurchaseOrder(PurchaseOrder $purchaseOrder){return response()->json($purchaseOrder->load('supplier','items.productVariant','receipts.items'));}
 public function confirmReceipt(GoodsReceipt $goodsReceipt,ConfirmGoodsReceiptAction $a):RedirectResponse{$a->handle($goodsReceipt);return back()->with('success','Goods receipt confirmed and inventory posted.');}
 public function storeInvoice(Request $r):RedirectResponse{$d=$r->validate(['supplier_id'=>'required|exists:suppliers,id','purchase_order_id'=>'nullable|exists:purchase_orders,id','goods_receipt_id'=>'nullable|exists:goods_receipts,id','invoice_date'=>'required|date','due_date'=>'nullable|date','subtotal'=>'required|numeric|min:0','discount'=>'nullable|numeric|min:0','tax'=>'nullable|numeric|min:0','notes'=>'nullable|string']);$total=$d['subtotal']-($d['discount']??0)+($d['tax']??0);$invoice=SupplierInvoice::create($d+['invoice_number'=>app(CodeGeneratorService::class)->generate('PINV',SupplierInvoice::max('id')+1),'discount'=>$d['discount']??0,'tax'=>$d['tax']??0,'total'=>$total,'remaining_amount'=>$total,'status'=>'unpaid']);return back()->with('success',"Invoice {$invoice->invoice_number} created.");}
 public function storePayment(Request $r,RecordSupplierPaymentAction $a):RedirectResponse{$d=$r->validate(['supplier_invoice_id'=>'required|exists:supplier_invoices,id','payment_date'=>'required|date','amount'=>'required|numeric|gt:0','payment_method'=>'required|string|max:50','reference'=>'nullable|string|max:255','notes'=>'nullable|string']);$a->handle($d);return back()->with('success','Supplier payment recorded.');}
 public function confirmReturn(PurchaseReturn $purchaseReturn,ConfirmPurchaseReturnAction $a):RedirectResponse{$a->handle($purchaseReturn);return back()->with('success','Purchase return confirmed and inventory posted.');}
}
